def countPathsWithXorValue(grid: List[List[int]], k: int) -> int:
    m, n = len(grid), len(grid[0])
    MOD = 10**9 + 7
    # dp[i][j] stores a dictionary or list of {xor_sum: count}
    dp = [[ [0]*16 for _ in range(n)] for _ in range(m)]

    dp[0][0][grid[0][0]] = 1

    for i in range(m):
        for j in range(n):
            for x in range(16):
                if dp[i][j][x] > 0:
                    count = dp[i][j][x]
                    # Down
                    if i + 1 < m:
                        target_xor = x ^ grid[i+1][j]
                        dp[i+1][j][target_xor] = (dp[i+1][j][target_xor] + count) % MOD
                    # Right
                    if j + 1 < n:
                        target_xor = x ^ grid[i][j+1]
                        dp[i][j+1][target_xor] = (dp[i][j+1][target_xor] + count) % MOD

    return dp[m-1][n-1][k]
