from typing import List

def countPathsWithXorValue(grid: List[List[int]], k: int) -> int:
    m, n = len(grid), len(grid[0])
    MOD = 10**9 + 7
    # dp[i][j] is a list of size 16 where index x stores count of paths to (i, j) with XOR x
    dp = [[ [0]*16 for _ in range(n)] for _ in range(m)]

    dp[0][0][grid[0][0]] = 1

    for i in range(m):
        for j in range(n):
            val = grid[i][j]
            # Optimization: If we are at (0,0), it's already initialized. 
            # However, for simplicity and speed in Python, we can just iterate.
            if i == 0 and j == 0: continue

            current_counts = dp[i][j]
            # From Top
            if i > 0:
                prev_row = dp[i-1][j]
                for x in range(16):
                    if prev_row[x] > 0:
                        current_counts[x ^ val] = (current_counts[x ^ val] + prev_row[x]) % MOD
            # From Left
            if j > 0:
                prev_col = dp[i][j-1]
                for x in range(16):
                    if prev_col[x] > 0:
                        current_counts[x ^ val] = (current_counts[x ^ val] + prev_col[x]) % MOD

    return dp[m-1][n-1][k]
