def minStartingIndex(s: str, pattern: str) -> int:
    n, m = len(s), len(pattern)
    for i in range(n - m + 1):
        mismatches = 0
        for j in range(m):
            if s[i + j] != pattern[j]:
                mismatches += 1
                if mismatches > 1:
                    break
        if mismatches <= 1:
            return i
    return -1
