from typing import List

def maxScore(n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
    # dp[j] represents the maximum score ending at city j after current day i
    dp = [-1] * n

    # Day 0 initialization
    for s in range(n):
        # Option 1: Start at city s and stay there on day 0
        dp[s] = max(dp[s], stayScore[0][s])
        # Option 2: Start at some city m and move to city d on day 0
        # Note: The problem says "choose any city as their starting point".
        # If they start at m and move to d, the score is travelScore[m][d].
        for d in range(n):
            dp[d] = max(dp[d], travelScore[s][d])

    # Iterate through days 1 to k-1
    for i in range(1, k):
        new_dp = [-1] * n
        for j in range(n):
            # Option: Stay at city j from day i-1 to day i
            if dp[j] != -1:
                new_dp[j] = max(new_dp[j], dp[j] + stayScore[i][j])

            # Option: Move from some city m to city j on day i
            for m in range(n):
                if dp[m] != -1:
                    new_dp[j] = max(new_dp[j], dp[m] + travelScore[m][j])
        dp = new_dp

    return max(dp)
```

