from typing import List
from collections import Counter

def countPairs(nums: List[int]) -> int:
    def get_variants(n: int) -> set:
        s = list(str(n))
        variants = {tuple(s)}
        # Try all possible swaps within the string representation
        for i in range(len(s)):
            for j in range(i + 1, len(s)):
                if s[i] != s[j]:
                    new_s = list(s)
                    new_s[i], new_s[j] = new_s[j], new_s[i]
                    variants.add(tuple(new_s))
        return variants

    count = 0
    # Since constraints are small (nums.length <= 100), O(N^2) is efficient enough.
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            s1 = str(nums[i])
            s2 = str(nums[j])

            # Quick check: lengths must be the same for them to potentially become equal
            if len(s1) != len(s2):
                continue

            v1 = get_variants(nums[i])
            v2 = get_variants(nums[j])

            # If any variant of nums[i] matches a variant of nums[j], they are "almost equal"
            # Actually, the logic is: can we make nums[i] == nums[j]? 
            # This happens if nums[j] is one of the variants of nums[i].
            if tuple(s2) in v1 or tuple(s1) in v2:
                count += 1

    return count
```

