def countOfSubstrings(word: str, k: int) -> int:
    vowels = {'a', 'e', 'i', 'o', 'u'}
    n = len(word)
    count = 0

    # Iterate through every possible starting position of the substring
    for i in range(n):
        current_vowels = set()
        consonant_count = 0

        # Expand the end position j
        for j in range(i, n):
            char = word[j]
            if char in vowels:
                current_vowels.add(char)
            else:
                consonant_count += 1

            # If we exceed k consonants, no need to expand further for this i
            if consonant_count > k:
                break

            # Check if current substring satisfies both conditions
            if len(current_vowels) == 5 and consonant_count == k:
                count += 1

    return count
