from typing import List
import collections

def sortMatrix(grid: List[List[int]]) -> List[List[int]]:
    n = len(grid)
    diagonals = collections.defaultdict(list)

    for r in range(n):
        for c in range(n):
            diagonals[r - c].append(grid[r][c])

    for k, values in diagonals.items():
        if k >= 0:
            # Bottom-left triangle (including middle) -> non-increasing
            values.sort(reverse=True)
        else:
            # Top-right triangle -> non-decreasing
            values.sort()

    diag_indices = collections.defaultdict(int)
    for r in range(n):
        for c in range(n):
            k = r - c
            grid[r][c] = diagonals[k][diag_indices[k]]
            diag_indices[k] += 1

    return grid
